styleFocus:
@media (max-width: 1100px) {
  .header { height: 64px; }
  .headerInner { width: calc(100% - 32px); height: 63px; gap: 8px; }
  .logoLink { min-width: 120px; min-height: 44px; }
  .logo { width: 120px; height: 40px; }
  .desktopNav, .rfqFull { display: none; }
  .rfqCompact, .menuButton { display: inline; }
  .headerRfq { min-height: 44px; padding: 0px 14px; }
  .menuButton { min-width: 64px; min-height: 44px; padding: 0px 12px; border: 1px solid rgb(0, 128, 120); border-radius: 6px; color: rgb(6, 43, 91); background: rgb(255, 255, 255); font: 600 14px Inter, Arial, sans-serif; }
  .mobileNav { position: absolute; top: 63px; right: 0px; left: 0px; display: grid; grid-template-columns: 1fr; max-height: calc(-64px + 100vh); overflow: auto; color: rgb(255, 255, 255); background: rgb(3, 27, 58); }
  .mobileNav[hidden] { display: none; }
  .header nav.mobileNav > a { position: relative; min-height: 52px; padding: 10px 24px; display: flex; align-items: center; justify-content: flex-start; border-bottom: 1px solid rgb(35, 70, 101); color: rgb(255, 255, 255); font-size: 16px; font-weight: 500; }
  .header nav.mobileNav > a[aria-current="page"] { padding-left: 32px; font-weight: 700; }
  .mobileNav a[aria-current="page"]::before { content: ""; position: absolute; top: 8px; bottom: 8px; left: 16px; width: 4px; background: rgb(0, 169, 157); }
  .mobileNav a:last-child { background: rgb(0, 128, 120); font-weight: 600; }
  .mobileNav a:focus-visible { outline: rgb(255, 255, 255) solid 3px; outline-offset: -4px; }
  .footerGrid { grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 36px 32px; }
  .brandColumn, .conversionColumn { grid-column: 1 / -1; }
}

